docker exec startuphafen-devcontainer-maildev-1 node -e "
const net=require('net');
const s=net.connect(1025,'127.0.0.1');
let buf='';
const steps=[
  {send:'EHLO validator',next:/^250/},
  {send:'MAIL FROM:<test@startuphafen.de>',next:/^250/},
  {send:'RCPT TO:<user@example.com>',next:/^250/},
  {send:'DATA',next:/^354/},
  {send:'From: noreply@startuphafen.de',next:/^354/},
  {send:'To: user@example.com',next:/^354/},
  {send:'Subject: validation-test',next:/^354/},
  {send:'Content-Type: text/plain',next:/^354/},
  {send:'',next:/^354/},
  {send:'This is a maildev validation email.',next:/^354/},
  {send:'',next:/^354/},
  {send:'.',next:/^250/},
  {send:'QUIT',next:/^221/}
];
let i=0, sent=0;
s.on('data',d=>{
  buf+=d.toString();
  const code=/^(\d{3})/.exec(buf);
  if(code && steps[i] && code[1]===steps[i].next[0].toString().slice(0,3)){
    buf='';
    if(sent>0) console.log(steps[i-1].send.slice(0,40),'->',code[1]);
    if(i<steps.length){ s.write(steps[i].send+'\r\n'); i++; sent++; }
    else s.end();
  }
});
s.on('end',()=>{ console.log('SMTP SESSION COMPLETE'); process.exit(0); });
setTimeout(()=>{ console.log('TIMEOUT step',i); process.exit(1);},8000);
"

